function leagueHistory(){const aliases={'Philadelphia Warriors':'GSW','San Francisco Warriors':'GSW','Golden State Warriors':'GSW','Minneapolis Lakers':'LAL','Los Angeles Lakers':'LAL','Syracuse Nationals':'PHI','Philadelphia 76ers':'PHI','Rochester Royals':'SAC','St. Louis Hawks':'ATL','Seattle SuperSonics':'OKC','Oklahoma City Thunder':'OKC','Fort Wayne Pistons':'DET','Detroit Pistons':'DET','Baltimore Bullets':'WAS','Washington Bullets':'WAS','Washington Wizards':'WAS'},key=n=>aliases[n]||n,awardOpts=[['champions','NBA CHAMPIONS'],...Object.entries(NBA_AWARD_HISTORY).map(([k,v])=>[k,v.label])],renderChampions=()=>{const counts={},chron=[...NBA_FINALS_HISTORY].reverse().map(x=>{const k=key(x.champion);counts[k]=(counts[k]||0)+1;return{...x,titleNo:counts[k]}}).reverse(),s=loadSeason(),saved=JSON.parse(localStorage.getItem('nbaGM.leagueHistory')||'[]'),future=[...saved,...(Array.isArray(s?.leagueHistory)?s.leagueHistory:[])].filter(x=>x?.champion&&x?.runnerUp&&x?.series).sort((a,b)=>String(b.season).localeCompare(String(a.season))),baseCounts={};for(const x of NBA_FINALS_HISTORY){const k=key(x.champion);baseCounts[k]=(baseCounts[k]||0)+1}for(const x of [...future].reverse()){const k=key(x.champion);baseCounts[k]=(baseCounts[k]||0)+1;x.titleNo=baseCounts[k]}return [...future,...chron].map(x=>`<div class="recordRow historyRow"><span>${x.season}</span><div><b>${x.champion} (${x.titleNo})</b><small>def. ${x.runnerUp}</small></div><strong>${x.series}</strong></div>`).join('')},renderAward=k=>{const a=NBA_AWARD_HISTORY[k],counts={},numbered=[...a.rows].reverse().map(([season,winner])=>{const names=winner.split(' / '),display=names.map(name=>{counts[name]=(counts[name]||0)+1;return `${name} (${counts[name]})`}).join(' / ');return{season,display}}).reverse();return numbered.map(x=>`<div class="recordRow historyRow awardHistoryRow"><span>${x.season}</span><div><b>${x.display}</b><small>${a.label}</small></div></div>`).join('')},draw=()=>{const k=$('#historyType').value;$('#historyRows').innerHTML=k==='champions'?renderChampions():renderAward(k)};app.innerHTML=shell(`${leagueBack()}<header class="leagueSubHead"><div class="eyebrow">NBA / BAA • HISTORICAL RECORDS</div><h1>LEAGUE HISTORY</h1><select id="historyType">${awardOpts.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('')}</select><div class="sub">Newest season first • number in brackets is that winner's career total at the time</div></header><section class="recordRows" id="historyRows"></section>`);$('#backLeagueHub').onclick=()=>{page='league';render()};$('#historyType').onchange=draw;draw();wireNav()}
function leagueTeam(){let t=TEAMS.find(x=>x.id===browseTeam)||TEAMS[0],ps=teamPlayers(t.id);app.innerHTML=shell(`<button class="back" id="backLeague">‹ ALL TEAMS</button><header class="top"><div class="eyebrow">LEAGUE ROSTER</div><h1 class="title">${t.city}<br>${t.name}</h1><div class="sub">${ps.length} players</div></header>${rosterRows(t.id)}`);$('#backLeague').onclick=()=>{page='league';render()};wirePlayers('league');wireNav()}
const isCurrentRookie=p=>Number(p?.exp||0)===0;
const CAREER_HIGH_SEEDS={
1641705:{pts:50,reb:23,ast:11,stl:6,blk:10},
1628368:{pts:60,reb:13,ast:16,stl:6,blk:4},
2544:{pts:61,reb:20,ast:19,stl:7,blk:5},
201939:{pts:62,reb:14,ast:16,stl:7,blk:3},
203999:{pts:61,reb:27,ast:22,stl:7,blk:5},
203507:{pts:64,reb:22,ast:20,stl:5,blk:7},
201935:{pts:61,reb:17,ast:21,stl:8,blk:5},
202681:{pts:60,reb:11,ast:18,stl:8,blk:4},
1628369:{pts:60,reb:19,ast:12,stl:5,blk:6},
202695:{pts:55,reb:16,ast:10,stl:7,blk:6},
202691:{pts:60,reb:11,ast:8,stl:5,blk:5}
};
const CAREER_HIGH_CACHE_KEY='nbaGM.careerHighs.v1';
function careerHighCache(){try{return JSON.parse(localStorage.getItem(CAREER_HIGH_CACHE_KEY)||'{}')}catch{return{}}}
function saveCareerHighCache(x){try{localStorage.setItem(CAREER_HIGH_CACHE_KEY,JSON.stringify(x))}catch{}}
function historicalCareerHighs(p){if(isCurrentRookie(p))return{pts:0,reb:0,ast:0,stl:0,blk:0,tpm:0};const cached=careerHighCache()[p.nbaId];return cached||CAREER_HIGH_SEEDS[Number(p.nbaId)]||{}}
async function fetchOfficialCareerHigh(p){if(isCurrentRookie(p))return null;try{const r=await fetch(`https://data.nba.com/data/v2022/json/mobile_teams/nba/2025/players/player_highs_${p.nbaId}_02.json`,{cache:'force-cache'});if(!r.ok)return null;const j=await r.json(),ca=j?.data?.pl?.ca;if(!ca)return null;const out={pts:+ca.pts?.val||0,reb:+ca.reb?.val||0,ast:+ca.ast?.val||0,stl:+ca.stl?.val||0,blk:+ca.blk?.val||0,tpm:+ca.tpm?.val||0};return out}catch{return null}}
async function hydrateCareerHighs(){const cache=careerHighCache(),todo=PLAYERS.filter(p=>!isCurrentRookie(p)&&!cache[p.nbaId]);if(!todo.length)return;let n=0;const worker=async()=>{while(n<todo.length){const p=todo[n++],v=await fetchOfficialCareerHigh(p);if(v){cache[p.nbaId]=v;saveCareerHighCache(cache)}}};await Promise.all(Array.from({length:Math.min(8,todo.length)},worker));document.dispatchEvent(new CustomEvent('nba-gm-careerhighs'))}
setTimeout(()=>hydrateCareerHighs(),300);
function careerHighsFor(p){const seed={...historicalCareerHighs(p)},s=loadSeason(),games=(s?.games||[]),keys=['pts','reb','ast','stl','blk','tpm'];for(const g of games)for(const x of (g.box||[]))if(Number(x.nbaId)===Number(p.nbaId)||x.name===p.name)for(const k of keys)seed[k]=Math.max(Number(seed[k]||0),Number(x[k]||0));return seed}
function player(){let p=PLAYERS.find(x=>x.nbaId===selected);if(!p){page=playerReturn==='league'?'leagueTeam':'team';return render()}let groups=[['SCORING',['inside','mid','three','finishing']],['PLAYMAKING',['passing','handle','offIQ']],['DEFENSE',['perimeterD','interiorD','steal','block']],['ATHLETIC',['speed','strength','vertical','stamina']]],highs=careerHighsFor(p),highLabels=[['pts','POINTS'],['reb','REBOUNDS'],['ast','ASSISTS'],['stl','STEALS'],['blk','BLOCKS'],['tpm','3-POINTERS']];app.innerHTML=shell(`<button class="back" id="back">‹ ${playerReturn==='league'?'TEAM ROSTER':'ROSTER'}</button><section class="playerHero"><img src="${portrait(p.nbaId)}"><div><div class="label">${p.team} • ${p.pos} • ${p.height}</div><h1>${p.name}</h1><div class="bigOvr">${overall(p)} <small>OVR</small></div><div class="sub">Age ${p.age} • ${potentialLabel(p.dev.ceiling)} Potential</div></div></section><div class="grid"><article class="card"><div class="label">2026–27 CONTRACT</div><div class="metric">${money(p)}</div><div class="sub">${p.contract?.verified?p.contract.years+' years remaining':'Salary audit pending'}</div></article><article class="card"><div class="label">CEILING</div><div class="metric">${p.dev.ceiling}</div><div class="sub">Peak age ${p.dev.peakAge}</div></article></div>${groups.map(([n,ks])=>`<div class="section">${n}</div><div class="ratingGrid">${ks.map(k=>`<div><span>${k.replace(/[A-Z]/g,m=>' '+m).toUpperCase()}</span><b>${p.ratings[k]}</b></div>`).join('')}</div>`).join('')}<div class="section">CAREER HIGHS</div><div class="ratingGrid careerHighGrid">${highLabels.map(([k,label])=>`<div><span>${label}</span><b>${highs[k]??'—'}</b></div>`).join('')}</div>`);$('#back').onclick=()=>{page=playerReturn==='league'?'leagueTeam':'team';render()};wireNav()}
function placeholder(kind){app.innerHTML=shell(`<header class="top"><div class="eyebrow">NBA GM</div><h1 class="title">${kind.toUpperCase()}</h1></header><section class="hero"><h2>Foundation ready.</h2></section>`);wireNav()}function wireNav(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{page=b.dataset.nav;render()})}function render(){if(save&&page==='team')repairRotation(save.team,rotationFor(save.team));if(!save)return setup();if(page==='home')return home();if(page==='team')return team();if(page==='league')return league();if(page==='leagueTeam')return leagueTeam();if(page==='player')return player();if(page==='rotation')return rotation();if(page==='coaches')return coaches();if(page==='finances')return finances();if(page==='injuries')return injuries();if(page==='gm')return gm();if(page==='settings')return settings();if(page==='trade')return trade();if(page==='tradeFinder')return tradeFinder();return placeholder(page)}document.addEventListener('seasonchange',()=>{if(page==='home')render()});document.addEventListener('nba-gm-home',()=>{page='home';render()});document.addEventListener('nba-gm-open-rotation',e=>{rotationReturnGameId=e.detail?.returnToGame?e.detail.gameId:null;page='rotation';render()});render();